CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, email TEXT UNIQUE, password TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE campaigns (id INTEGER PRIMARY KEY, name TEXT, advertiser TEXT, budget INTEGER, spent INTEGER DEFAULT 0, impressions INTEGER DEFAULT 0, clicks INTEGER DEFAULT 0, status TEXT DEFAULT 'active', starts_at TEXT, ends_at TEXT);
CREATE TABLE ads (id INTEGER PRIMARY KEY, campaign_id INTEGER, title TEXT, type TEXT, destination_url TEXT, status TEXT DEFAULT 'active');
CREATE TABLE sites (id INTEGER PRIMARY KEY, name TEXT, domain TEXT, impressions INTEGER DEFAULT 0, clicks INTEGER DEFAULT 0, status TEXT DEFAULT 'active');
CREATE TABLE events (id INTEGER PRIMARY KEY, ad_id INTEGER, event_type TEXT, referer TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
